package com.aistock.scheduler.security;
import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import org.springframework.context.annotation.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.web.servlet.FilterRegistrationBean;import org.springframework.web.cors.*;import org.springframework.web.filter.CorsFilter;
@Configuration public class AdminTaskSecurityConfiguration {
 @Bean FilterRegistrationBean<AdminTaskAccessFilter> adminTaskAccess(SessionIdentityClient client,@Value("${aistock.internal.token:}")String token,ObjectMapper mapper,@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){var bean=new FilterRegistrationBean<>(new AdminTaskAccessFilter(client,token,mapper,new HashSet<>(Arrays.stream(origins.split(",")).map(String::strip).filter(v->!v.isEmpty()).toList())));bean.setOrder(-90);bean.addUrlPatterns("/api/v1/admin/market-data/*","/api/v1/admin/tasks","/api/v1/admin/tasks/*","/api/v1/admin/statistics","/api/v1/admin/statistics/*");return bean;}
 @Bean FilterRegistrationBean<CorsFilter> adminTaskCors(@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){
  var cors=new CorsConfiguration();cors.setAllowedOrigins(Arrays.stream(origins.split(",")).map(String::strip).filter(s->!s.isEmpty()).toList());cors.setAllowCredentials(true);cors.setAllowedMethods(List.of("GET","OPTIONS"));cors.setAllowedHeaders(List.of("Content-Type","X-Trace-Id"));
  var source=new UrlBasedCorsConfigurationSource();source.registerCorsConfiguration("/api/v1/admin/statistics/tasks",cors);source.registerCorsConfiguration("/api/v1/admin/tasks",cors);
  var write=new CorsConfiguration(cors);write.setAllowedMethods(List.of("POST","OPTIONS"));write.setAllowedHeaders(List.of("Content-Type","X-Trace-Id","X-Aistock-Admin-Action"));
  source.registerCorsConfiguration("/api/v1/admin/tasks/*/retry",write);source.registerCorsConfiguration("/api/v1/admin/tasks/*/cancel",write);source.registerCorsConfiguration("/api/v1/admin/tasks/training/*/cancel",write);source.registerCorsConfiguration("/api/v1/admin/tasks/**",cors);
  var filter=new CorsFilter(source){@Override protected void doFilterInternal(jakarta.servlet.http.HttpServletRequest r,jakarta.servlet.http.HttpServletResponse s,jakarta.servlet.FilterChain chain)throws java.io.IOException,jakarta.servlet.ServletException{s.setHeader("Cache-Control","no-store");if(!"OPTIONS".equals(r.getMethod())&&!AdminTaskAccessFilter.allowed(r.getMethod(),r.getRequestURI())){chain.doFilter(r,s);return;}super.doFilterInternal(r,s,chain);}};
  var bean=new FilterRegistrationBean<CorsFilter>(filter);bean.setOrder(-100);bean.addUrlPatterns("/api/v1/admin/tasks","/api/v1/admin/tasks/*","/api/v1/admin/statistics","/api/v1/admin/statistics/*");return bean;
 }
}
